import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"인덱싱 관리","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 로컬 드라이브 (Local Drives)","slug":"_1-로컬-드라이브-local-drives","link":"#_1-로컬-드라이브-local-drives","children":[]},{"level":2,"title":"2. 네트워크 드라이브 (Network Drives)","slug":"_2-네트워크-드라이브-network-drives","link":"#_2-네트워크-드라이브-network-drives","children":[]},{"level":2,"title":"3. WSL (Linux용 Windows 하위 시스템)","slug":"_3-wsl-linux용-windows-하위-시스템","link":"#_3-wsl-linux용-windows-하위-시스템","children":[]},{"level":2,"title":"4. 폴더 (Folders)","slug":"_4-폴더-folders","link":"#_4-폴더-folders","children":[]},{"level":2,"title":"5. 제외 규칙 (Exclusions)","slug":"_5-제외-규칙-exclusions","link":"#_5-제외-규칙-exclusions","children":[{"level":3,"title":"경로 제외 (Path Exclusions)","slug":"경로-제외-path-exclusions","link":"#경로-제외-path-exclusions","children":[]},{"level":3,"title":"Glob 규칙 (Glob Rules)","slug":"glob-규칙-glob-rules","link":"#glob-규칙-glob-rules","children":[]},{"level":3,"title":"정규식 규칙 (Regex Rules)","slug":"정규식-규칙-regex-rules","link":"#정규식-규칙-regex-rules","children":[]}]}],"relativePath":"ko-KR/user-guide/settings/index-drives.md","filePath":"ko-KR/user-guide/settings/index-drives.md","lastUpdated":1791053655000}`),a={name:`ko-KR/user-guide/settings/index-drives.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="인덱싱-관리" tabindex="-1">인덱싱 관리 <a class="header-anchor" href="#인덱싱-관리" aria-label="Permalink to “인덱싱 관리”">​</a></h1><p>인덱스 설정 페이지에서는 로컬 드라이브, 네트워크 공유, WSL 및 사용자 지정 폴더에 대한 인덱싱 범위, 갱신 주기 및 제외 규칙을 정밀하게 제어합니다. 상단에는 <strong>로컬 드라이브</strong>, <strong>네트워크 드라이브</strong>, <strong>WSL</strong>(배포판 감지 시에만 표시), <strong>폴더</strong>, <strong>제외 규칙</strong>의 5개 탭이 제공됩니다.</p><h2 id="_1-로컬-드라이브-local-drives" tabindex="-1">1. 로컬 드라이브 (Local Drives) <a class="header-anchor" href="#_1-로컬-드라이브-local-drives" aria-label="Permalink to “1. 로컬 드라이브 (Local Drives)”">​</a></h2><ul><li><strong>상단 요약 카드</strong>: 현재 인덱싱된 물리 드라이브 수와 총 파일/폴더 수를 보여주며, 전체 재구축을 실행하는 <strong>인덱스 재구축</strong> 버튼을 제공합니다.</li><li><strong>드라이브 목록 행</strong>: <ul><li><strong>활성화 체크박스</strong>: 파티션별 인덱싱을 독립적으로 토글.</li><li><strong>파일 시스템 및 상태</strong>: 파일 시스템 종류(NTFS, ReFS, FAT32, exFAT 등), 상태 및 인덱싱된 항목 수 표시.</li><li><strong>개별 조작</strong>: <strong>재구축</strong> 및 <strong>제거</strong> 버튼. 스캔 진행 중에는 <strong>중지</strong> 버튼이 동적으로 나타납니다.</li></ul></li><li><strong>실시간 감지</strong>: NTFS / ReFS 볼륨은 Windows USN 변경 저널을 읽어 밀리초 단위로 동기화하며, FAT32 / exFAT는 파일 변경 이벤트를 실시간 감지합니다.</li><li><strong>중단 없는 재구축</strong>: 드라이브를 재구축하는 동안에도 새 인덱스가 완성될 때까지 기존 인덱스가 검색에 계속 응답하므로 검색이 중단되지 않습니다. 중단되더라도 다음 실행 시 중단점부터 재개됩니다.</li></ul><h2 id="_2-네트워크-드라이브-network-drives" tabindex="-1">2. 네트워크 드라이브 (Network Drives) <a class="header-anchor" href="#_2-네트워크-드라이브-network-drives" aria-label="Permalink to “2. 네트워크 드라이브 (Network Drives)”">​</a></h2><ul><li><strong>네트워크 공유 지원</strong>: 매핑된 Windows 네트워크 드라이브(SMB / NAS) 목록 표시.</li><li><strong>새로고침 모드 (Refresh Mode)</strong>: 로컬 저널이 없으므로 정기 스캔 주기를 설정: <ul><li><strong>수동</strong> —— &quot;인덱스 재구축&quot; 클릭 시에만 스캔.</li><li><strong>15분마다</strong> —— 공동 작업용 공유 폴더 추천.</li><li><strong>매시간</strong> —— 균형 잡힌 정기 스캔.</li><li><strong>매일</strong> —— 보관용 공유 폴더 추천.</li></ul></li><li><strong>심볼릭 링크 순환 보호</strong>: NAS 상의 재귀 심볼릭 링크나 정션으로 인한 무한 루프를 방지하기 위해 순환 감지 알고리즘이 중복 경로를 자동 건너뜁니다.</li></ul><h2 id="_3-wsl-linux용-windows-하위-시스템" tabindex="-1">3. WSL (Linux용 Windows 하위 시스템) <a class="header-anchor" href="#_3-wsl-linux용-windows-하위-시스템" aria-label="Permalink to “3. WSL (Linux용 Windows 하위 시스템)”">​</a></h2><p>WSL 배포판이 설치되어 있는 경우에만 자동으로 나타납니다.</p><ul><li><strong>자동 감지</strong>: Ubuntu, Debian, Arch 등 설치된 WSL 배포판 자동 인식.</li><li><strong>상태 및 스케줄</strong>: 네트워크 드라이브와 동일한 상태 관리 및 새로고침 모드(수동 / 15분 / 매시간 / 매일) 제공.</li><li><strong>제로 I/O 검색</strong>: WSL 파일 검색 시 메모리 인덱스를 직접 쿼리하여 Linux 서브시스템에 부하를 주지 않습니다.</li></ul><h2 id="_4-폴더-folders" tabindex="-1">4. 폴더 (Folders) <a class="header-anchor" href="#_4-폴더-folders" aria-label="Permalink to “4. 폴더 (Folders)”">​</a></h2><p>드라이브 전체가 아닌 특정 작업 폴더만 인덱싱하고 싶을 때 사용합니다.</p><ul><li><strong>다중 선택 추가</strong>: <strong>폴더 추가</strong>를 클릭하고 <code>Ctrl</code>이나 <code>Shift</code>를 누른 채 여러 폴더를 일괄 선택하여 추가할 수 있습니다.</li><li><strong>UNC 경로 지원</strong>: <code>\\\\server\\share\\projects</code>와 같은 네트워크 UNC 경로도 직접 등록 가능합니다.</li><li><strong>개별 스케줄 설정</strong>: 각 폴더마다 독립적인 활성화 스위치, 항목 카운터 및 새로고침 모드 드롭다운이 제공됩니다.</li></ul><h2 id="_5-제외-규칙-exclusions" tabindex="-1">5. 제외 규칙 (Exclusions) <a class="header-anchor" href="#_5-제외-규칙-exclusions" aria-label="Permalink to “5. 제외 규칙 (Exclusions)”">​</a></h2><p>제외 규칙은 검색 결과를 걸러내고 네트워크, WSL, 폴더 인덱스의 탐색 범위를 제한합니다. 로컬 드라이브의 인덱싱은 중단하지 않습니다. 로컬 볼륨은 항상 전체가 탐색되므로 여기에 <code>E:\\</code>를 적어도 결과만 숨겨집니다. 로컬 드라이브의 인덱싱을 중단하려면 위의 <strong>로컬 드라이브</strong> 탭에서 끄세요. 규칙은 3개의 하위 탭으로 나뉩니다.</p><h3 id="경로-제외-path-exclusions" tabindex="-1">경로 제외 (Path Exclusions) <a class="header-anchor" href="#경로-제외-path-exclusions" aria-label="Permalink to “경로 제외 (Path Exclusions)”">​</a></h3><ul><li><strong>접두사 일치</strong>: <code>D:\\Cache</code> 또는 환경 변수(<code>%ProgramData%</code>, <code>%APPDATA%</code>)를 지정하여 제외.</li></ul><h3 id="glob-규칙-glob-rules" tabindex="-1">Glob 규칙 (Glob Rules) <a class="header-anchor" href="#glob-규칙-glob-rules" aria-label="Permalink to “Glob 규칙 (Glob Rules)”">​</a></h3><ul><li><strong>와일드카드 문법</strong>: <ul><li><code>*</code>: 폴더 단일 계층 내 임의 문자(예: <code>*.tmp</code>, <code>*.log</code>).</li><li><code>**</code>: 재귀적 하위 디렉토리 일치(예: <code>**/node_modules/**</code>, <code>**/bin/**</code>, <code>**/obj/**</code>).</li></ul></li></ul><h3 id="정규식-규칙-regex-rules" tabindex="-1">정규식 규칙 (Regex Rules) <a class="header-anchor" href="#정규식-규칙-regex-rules" aria-label="Permalink to “정규식 규칙 (Regex Rules)”">​</a></h3><ul><li><strong>고급 정규식 일치</strong>: 숨김 파일(<code>^\\.</code>)이나 Office 임시 잠금 파일(<code>~\\$</code>) 등을 정밀하게 제외.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>제외 규칙은 <strong>개별 추가</strong> 및 <strong>텍스트 일괄 가져오기/내보내기</strong>를 모두 지원합니다. <strong>목록에서 생성</strong>을 눌러 내보내고, 편집 후 <strong>목록에 적용</strong>을 눌러 일괄 갱신할 수 있습니다.</p></div>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};